5: /// 将已判定可用贴图的 gizmo 图标顶点固化为本帧 GPU 缓冲；空图标不生成绘制命令。
6: pub(crate) fn build_icon_buffer(
7:     device: &wgpu::Device,
8:     label: &str,
9:     vertices: &[IconVertex],
10: ) -> Option<(wgpu::Buffer, u32)> {
11:     if vertices.is_empty() {
12:         return None;
13:     }
14:     let buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
15:         label: Some(label),
16:         contents: bytemuck::cast_slice(vertices),
17:         usage: wgpu::BufferUsages::VERTEX,
18:     });
19:     Some((buffer, vertices.len() as u32))
20: }

