5: const GRID_HALF_EXTENT: i32 = 10;
6: const GRID_VERTICES_PER_INDEX: usize = 4;
7: const GRID_INDEX_COUNT: usize = (GRID_HALF_EXTENT * 2 + 1) as usize;
8: 
9: /// 生成固定范围的编辑器参考网格；overlay 初始化时创建一次缓冲，随相机由线条管线投影。
10: pub(crate) fn build_grid_vertices() -> Vec<LineVertex> {
11:     let mut vertices = Vec::with_capacity(GRID_INDEX_COUNT * GRID_VERTICES_PER_INDEX);
12:     let extent = GRID_HALF_EXTENT as f32;
13:     for index in -GRID_HALF_EXTENT..=GRID_HALF_EXTENT {
14:         let color = if index == 0 {
15:             Vec4::new(0.24, 0.36, 0.88, 1.0)
16:         } else if index % 5 == 0 {
17:             Vec4::new(0.22, 0.24, 0.3, 1.0)
18:         } else {
19:             Vec4::new(0.16, 0.17, 0.2, 1.0)
20:         };
21:         let z = index as f32;
22:         vertices.push(LineVertex::new(Vec3::new(-extent, 0.0, z), color));
23:         vertices.push(LineVertex::new(Vec3::new(extent, 0.0, z), color));
24:         vertices.push(LineVertex::new(Vec3::new(z, 0.0, -extent), color));
25:         vertices.push(LineVertex::new(Vec3::new(z, 0.0, extent), color));
26:     }
27:     vertices
28: }
