8: /// 沿当前相机 right/up 构造面向视口的贴图图标；仅在图标 atlas 有可用绑定时由 gizmo 准备阶段调用。
9: pub(crate) fn build_icon_quad_vertices(
10:     icon: &OverlayBillboardIcon,
11:     right: Vec3,
12:     up: Vec3,
13: ) -> [IconVertex; 6] {
14:     let half = icon_world_size(icon) * 0.5;
15:     let top_left = icon.position - right * half + up * half;
16:     let top_right = icon.position + right * half + up * half;
17:     let bottom_left = icon.position - right * half - up * half;
18:     let bottom_right = icon.position + right * half - up * half;
19:     [
20:         IconVertex::new(top_left, [0.0, 0.0], icon.tint),
21:         IconVertex::new(bottom_left, [0.0, 1.0], icon.tint),
22:         IconVertex::new(top_right, [1.0, 0.0], icon.tint),
23:         IconVertex::new(top_right, [1.0, 0.0], icon.tint),
24:         IconVertex::new(bottom_left, [0.0, 1.0], icon.tint),
25:         IconVertex::new(bottom_right, [1.0, 1.0], icon.tint),
26:     ]
27: }

