1: use crate::core::math::{Transform, Vec3, Vec4};
2: 
3: use crate::graphics::scene::scene_renderer::primitives::LineVertex;
4: 
5: /// 将相机视锥辅助形状投到世界空间；只供 scene gizmo 的线框路径，不参与真实相机裁剪。
6: pub(crate) fn append_frustum(
7:     vertices: &mut Vec<LineVertex>,
8:     transform: Transform,
9:     fov_y_radians: f32,
10:     aspect_ratio: f32,
11:     z_near: f32,
12:     z_far: f32,
13:     color: Vec4,
14: ) {
15:     let near_half_height = (fov_y_radians * 0.5).tan() * z_near;
16:     let near_half_width = near_half_height * aspect_ratio.max(0.001);
17:     let far_half_height = (fov_y_radians * 0.5).tan() * z_far;
18:     let far_half_width = far_half_height * aspect_ratio.max(0.001);
19:     let matrix = transform.matrix();
20:     let near = [
21:         Vec3::new(-near_half_width, near_half_height, -z_near),
22:         Vec3::new(near_half_width, near_half_height, -z_near),
23:         Vec3::new(near_half_width, -near_half_height, -z_near),
24:         Vec3::new(-near_half_width, -near_half_height, -z_near),
25:     ]
26:     .map(|point| matrix.transform_point3(point));
27:     let far = [
28:         Vec3::new(-far_half_width, far_half_height, -z_far),
29:         Vec3::new(far_half_width, far_half_height, -z_far),
30:         Vec3::new(far_half_width, -far_half_height, -z_far),
31:         Vec3::new(-far_half_width, -far_half_height, -z_far),
32:     ]
33:     .map(|point| matrix.transform_point3(point));
34:     for (a, b) in [(0, 1), (1, 2), (2, 3), (3, 0)] {
35:         vertices.push(LineVertex::new(near[a], color));
36:         vertices.push(LineVertex::new(near[b], color));
37:         vertices.push(LineVertex::new(far[a], color));
38:         vertices.push(LineVertex::new(far[b], color));
39:         vertices.push(LineVertex::new(near[a], color));
40:         vertices.push(LineVertex::new(far[a], color));
41:     }
42: }

