6: /// 摄像机贴图缺失时的世界空间线框回退；沿当前相机基向量绘制，保持可辨识的视口图标。
7: pub(in crate::graphics::scene::scene_renderer::primitives::scene_gizmo::append) fn append_camera_icon_fallback_lines(
8:     vertices: &mut Vec<LineVertex>,
9:     icon: &OverlayBillboardIcon,
10:     right: Vec3,
11:     up: Vec3,
12:     size: f32,
13: ) {
14:     let half = size * 0.5;
15:     let left = icon.position - right * half;
16:     let right_pt = icon.position + right * half;
17:     let top = icon.position + up * half;
18:     let bottom = icon.position - up * half;
19:     vertices.push(LineVertex::new(left, icon.tint));
20:     vertices.push(LineVertex::new(right_pt, icon.tint));
21:     vertices.push(LineVertex::new(top, icon.tint));
22:     vertices.push(LineVertex::new(bottom, icon.tint));
23:     vertices.push(LineVertex::new(left, icon.tint));
24:     vertices.push(LineVertex::new(top, icon.tint));
25:     vertices.push(LineVertex::new(top, icon.tint));
26:     vertices.push(LineVertex::new(right_pt, icon.tint));
27:     vertices.push(LineVertex::new(right_pt, icon.tint));
28:     vertices.push(LineVertex::new(bottom, icon.tint));
29:     vertices.push(LineVertex::new(bottom, icon.tint));
30:     vertices.push(LineVertex::new(left, icon.tint));
31: }

1: use crate::core::framework::render::OverlayBillboardIcon;
2: use crate::core::math::Vec3;
3: 
4: use crate::graphics::scene::scene_renderer::primitives::LineVertex;
5: 
6: use super::super::super::line_geometry::append_cross;
7: 
8: /// 方向光贴图缺失时绘制十字与斜线轮廓；尺寸和颜色沿用对应贴图图标。
9: pub(in crate::graphics::scene::scene_renderer::primitives::scene_gizmo::append) fn append_directional_light_icon_fallback_lines(
10:     vertices: &mut Vec<LineVertex>,
11:     icon: &OverlayBillboardIcon,
12:     right: Vec3,
13:     up: Vec3,
14:     size: f32,
15: ) {
16:     append_cross(vertices, icon.position, size, icon.tint, right, up);
17: 
18:     let diagonal = (right + up).normalize_or_zero();
19:     vertices.push(LineVertex::new(
20:         icon.position - diagonal * size * 0.7,
21:         icon.tint,
22:     ));
23:     vertices.push(LineVertex::new(
24:         icon.position + diagonal * size * 0.7,
25:         icon.tint,
26:     ));
27: 
28:     let diagonal = (right - up).normalize_or_zero();
29:     vertices.push(LineVertex::new(
30:         icon.position - diagonal * size * 0.7,
31:         icon.tint,
32:     ));
33:     vertices.push(LineVertex::new(
34:         icon.position + diagonal * size * 0.7,
35:         icon.tint,
36:     ));
37: }

