1: use crate::core::framework::render::{SceneGizmoOverlayExtract, ViewportIconId};
2: 
3: use crate::graphics::scene::scene_renderer::primitives::LineVertex;
4: use crate::graphics::types::ViewportRenderFrame;
5: 
6: use super::super::super::line_geometry::push_line;
7: use super::super::append::{
8:     append_icon_fallback_lines, append_wire_shape, icon_fallback_vertex_capacity,
9:     wire_shape_vertex_capacity,
10: };
11: 
12: const LINE_VERTEX_CAPACITY: usize = 2;
13: 
14: fn scene_gizmo_line_vertex_capacity<F>(
15:     gizmos: &[SceneGizmoOverlayExtract],
16:     has_icon_texture: &F,
17: ) -> usize
18: where
19:     F: Fn(ViewportIconId) -> bool,
20: {
21:     gizmos
22:         .iter()
23:         .map(|gizmo| {
24:             let line_capacity = gizmo.lines.len().saturating_mul(LINE_VERTEX_CAPACITY);
25:             let wire_capacity = gizmo
26:                 .wire_shapes
27:                 .iter()
28:                 .map(wire_shape_vertex_capacity)
29:                 .fold(0usize, usize::saturating_add);
30:             let icon_capacity = gizmo
31:                 .icons
32:                 .iter()
33:                 .filter(|icon| !has_icon_texture(icon.id))
34:                 .map(icon_fallback_vertex_capacity)
35:                 .fold(0usize, usize::saturating_add);
36:             line_capacity
37:                 .saturating_add(wire_capacity)
38:                 .saturating_add(icon_capacity)
39:         })
40:         .fold(0usize, usize::saturating_add)
41: }
42: 
43: /// 聚合已抽取的 gizmo 线、线框形状及缺失图标回退；贴图图标由 scene_gizmo_pass 另行准备。
44: /// has_icon_texture 必须与本帧 atlas 准备状态一致，以免贴图与线框同时出现或同时缺席。
45: pub(crate) fn build_scene_gizmo_line_vertices<F>(
46:     frame: &ViewportRenderFrame,
47:     has_icon_texture: F,
48: ) -> Vec<LineVertex>
49: where
50:     F: Fn(ViewportIconId) -> bool,
51: {
52:     let vertex_capacity =
53:         scene_gizmo_line_vertex_capacity(&frame.overlays().scene_gizmos, &has_icon_texture);
54:     let mut vertices = Vec::with_capacity(vertex_capacity);
55:     let camera = frame.effective_camera();
56:     let camera_right = camera.transform.right();
57:     let camera_up = camera.transform.up();
58:     for gizmo in &frame.overlays().scene_gizmos {
59:         for line in &gizmo.lines {
60:             push_line(&mut vertices, line);
61:         }
62:         for shape in &gizmo.wire_shapes {
63:             append_wire_shape(&mut vertices, shape);
64:         }
65:         for icon in &gizmo.icons {
66:             if !has_icon_texture(icon.id) {
67:                 append_icon_fallback_lines(&mut vertices, icon, camera_right, camera_up);
68:             }
69:         }
70:     }
71:     vertices
72: }
