11: impl SceneUniform {
12:     pub(crate) fn from_frame(frame: &ViewportRenderFrame) -> Self {
13:         let camera = frame.effective_camera();
14:         let (ambient_color, lightmapped_ambient_color) = if frame.preview().lighting_enabled {
15:             authored_ambient_colors(frame, RenderVec3::splat(0.2))
16:         } else {
17:             let fallback = RenderVec3::splat(0.55).extend(1.0).to_array();
18:             (fallback, fallback)
19:         };
20: 
21:         let matrix_pair =
22:             ViewProjectionMatrixPair::from_camera(&camera, frame.render_region().local_size());
23:         let view_proj = matrix_pair.clip_from_world_jittered;
24:         let view_proj_unjittered = matrix_pair.clip_from_world_unjittered;
25:         let (previous_view_proj_unjittered, motion_params) =
26:             previous_motion_view_projection(frame, &camera, view_proj_unjittered);
27:         let skybox = &frame.environment().skybox;
28:         let sky_params = skybox.procedural;
29:         let authored_environment_rotation = skybox.rotation_radians();
30:         let environment_rotation = if authored_environment_rotation.is_finite() {
31:             authored_environment_rotation
32:         } else {
33:             0.0
34:         };
35:         let environment_rotation_sin_cos = if environment_rotation == 0.0 {
36:             [0.0, 1.0, 0.0, 0.0]
37:         } else {
38:             let (environment_rotation_sin, environment_rotation_cos) =
39:                 environment_rotation.sin_cos();
40:             [environment_rotation_sin, environment_rotation_cos, 1.0, 0.0]
41:         };
42:         let resolved_sun = sky_params.resolved_sun();
43:         let scene_sun_direction =
44:             resolved_sun.direction_for_sampling_rotation(environment_rotation);
45:         let source_cubemap_environment = frame.source_cubemap_environment();
46:         let has_ibl_source = match skybox.mode {
47:             SkyboxMode::Disabled => false,
48:             SkyboxMode::ProceduralGradient => true,
49:             SkyboxMode::SourceCubemap => source_cubemap_environment.is_some(),
50:         };
51:         let has_source_cubemap_irradiance = source_cubemap_environment
52:             .is_some_and(|environment| environment.irradiance_cube().is_some());
53:         let environment_sample_params = match skybox.mode {
54:             SkyboxMode::Disabled | SkyboxMode::ProceduralGradient => {
55:                 [skybox.mode as u32 as f32, 0.0, 0.0, 0.0]
56:             }
57:             SkyboxMode::SourceCubemap => source_cubemap_environment
58:                 .map(|environment| {
59:                     [
60:                         skybox.mode as u32 as f32,
61:                         environment.mip_chain.source_face_size() as f32,
62:                         environment.mip_chain.pmrem_face_size() as f32,
63:                         environment.mip_chain.pmrem_mip_count() as f32,
64:                     ]
65:                 })
66:                 .unwrap_or([skybox.mode as u32 as f32, 0.0, 0.0, 0.0]),
67:         };
68:         Self {
69:             view_proj: render_mat4_or(view_proj, RenderMat4::IDENTITY).to_cols_array_2d(),
70:             view_proj_unjittered: render_mat4_or(view_proj_unjittered, RenderMat4::IDENTITY)
71:                 .to_cols_array_2d(),
72:             inverse_view_proj: render_mat4_or(view_proj_unjittered.inverse(), RenderMat4::IDENTITY)
73:                 .to_cols_array_2d(),
74:             ambient_color,
75:             lightmapped_ambient_color,
76:             previous_view_proj_unjittered,
77:             motion_params,
78:             jitter_params: jitter_params(&camera),
79:             camera_world_position: render_vec3_or(camera.transform.translation, RenderVec3::ZERO)
80:                 .extend(0.0)
81:                 .to_array(),
82:             camera_view_direction: camera_view_direction(&camera),
83:             sky_horizon_color: render_vec4_or(
84:                 sky_params.horizon_color,
85:                 crate::core::math::Vec4::ZERO,
86:             )
87:             .to_array(),
88:             sky_zenith_color: render_vec4_or(
89:                 sky_params.zenith_color,
90:                 crate::core::math::Vec4::ZERO,
91:             )
92:             .to_array(),
93:             sky_ground_color: render_vec4_or(
94:                 sky_params.ground_color,
95:                 crate::core::math::Vec4::ZERO,
96:             )
97:             .to_array(),
98:             sky_sun_direction: scene_sun_direction.to_array(),
99:             sky_sun_color_radius: [
100:                 sky_params.sun_color.x,
101:                 sky_params.sun_color.y,
102:                 sky_params.sun_color.z,
103:                 sky_params.sun_angular_radius_radians,
104:             ],
105:             sky_sun_params: resolved_sun.intensity_and_cosines.to_array(),
106:             environment_params: [
107:                 if has_source_cubemap_irradiance {
108:                     1.0
109:                 } else {
110:                     0.0
111:                 },
112:                 skybox.intensity().max(0.0),
113:                 environment_rotation,
114:                 if has_ibl_source { 1.0 } else { 0.0 },
115:             ],
116:             environment_sample_params,
117:             environment_rotation_sin_cos,
118:         }
119:     }
