121:     pub(crate) fn from_hit_proxy_frame(frame: &ViewportRenderFrame, pixel: UVec2) -> Option<Self> {
122:         let crop = hit_proxy_clip_crop(pixel, frame.render_region())?;
123:         let mut uniform = Self::from_frame(frame);
124:         let jittered = crop * Mat4::from_cols_array_2d(&uniform.view_proj);
125:         let unjittered = crop * Mat4::from_cols_array_2d(&uniform.view_proj_unjittered);
126:         uniform.view_proj = render_mat4_or(jittered, RenderMat4::IDENTITY).to_cols_array_2d();
127:         uniform.view_proj_unjittered =
128:             render_mat4_or(unjittered, RenderMat4::IDENTITY).to_cols_array_2d();
129:         uniform.inverse_view_proj =
130:             render_mat4_or(unjittered.inverse(), RenderMat4::IDENTITY).to_cols_array_2d();
131:         Some(uniform)
132:     }
133: }
