135: fn hit_proxy_clip_crop(pixel: UVec2, region: ViewportRenderRegion) -> Option<Mat4> {
136:     let origin = region.physical_position();
137:     let size = region.physical_size();
138:     if pixel.x < origin.x || pixel.y < origin.y {
139:         return None;
140:     }
141:     let local = pixel - origin;
142:     if local.x >= size.x || local.y >= size.y {
143:         return None;
144:     }
145:     let width = size.x as f32;
146:     let height = size.y as f32;
147:     let center_x = 2.0 * (local.x as f32 + 0.5) / width - 1.0;
148:     let center_y = 1.0 - 2.0 * (local.y as f32 + 0.5) / height;
149:     Some(Mat4::from_cols_array_2d(&[
150:         [width, 0.0, 0.0, 0.0],
151:         [0.0, height, 0.0, 0.0],
152:         [0.0, 0.0, 1.0, 0.0],
153:         [-width * center_x, -height * center_y, 0.0, 1.0],
154:     ]))
155: }
156: 
157: fn previous_motion_view_projection(
158:     frame: &ViewportRenderFrame,
159:     camera: &crate::core::framework::render::ViewportCameraSnapshot,
160:     fallback_view_proj: Mat4,
161: ) -> ([[f32; 4]; 4], [f32; 4]) {
162:     let Some(previous_camera) = frame.previous_motion_vector_camera() else {
163:         return (
164:             render_mat4_or(fallback_view_proj, RenderMat4::IDENTITY).to_cols_array_2d(),
165:             [0.0, 0.0, 0.0, 0.0],
166:         );
167:     };
168:     let params =
169:         VelocityCameraParams::from_cameras(frame.viewport_size, camera, previous_camera, true);
170:     if !params.is_enabled() {
171:         return (
172:             render_mat4_or(fallback_view_proj, RenderMat4::IDENTITY).to_cols_array_2d(),
173:             [0.0, 0.0, 0.0, 0.0],
174:         );
175:     }
176: 
177:     (params.previous_clip_from_world(), [1.0, 0.0, 0.0, 0.0])
178: }
179: 
180: fn jitter_params(camera: &crate::core::framework::render::ViewportCameraSnapshot) -> [f32; 4] {
181:     [
182:         camera.temporal_jitter.offset_pixels.x,
183:         camera.temporal_jitter.offset_pixels.y,
184:         camera.temporal_jitter.sequence_index as f32,
185:         if camera.temporal_jitter.sequence_index > 0 {
186:             1.0
187:         } else {
188:             0.0
189:         },
190:     ]
191: }
192: 
193: fn camera_view_direction(
194:     camera: &crate::core::framework::render::ViewportCameraSnapshot,
195: ) -> [f32; 4] {
196:     let view_direction = render_vec3_or(
197:         camera.transform.rotation * crate::core::math::Vec3::Z,
198:         RenderVec3::Z,
199:     )
200:     .normalize_or_zero();

201:     [
202:         view_direction.x,
203:         view_direction.y,
204:         view_direction.z,
205:         match camera.projection_mode {
206:             ProjectionMode::Orthographic => 1.0,
207:             ProjectionMode::Perspective => 0.0,
208:         },
209:     ]
210: }
211: 
212: fn authored_ambient_colors(
213:     frame: &crate::graphics::types::ViewportRenderFrame,
214:     fallback: RenderVec3,
215: ) -> ([f32; 4], [f32; 4]) {
216:     if frame.ambient_lights().is_empty() {
217:         let fallback = fallback.extend(1.0).to_array();
218:         return (fallback, fallback);
219:     }
220: 
221:     let (ambient, lightmapped_ambient) = frame.ambient_lights().iter().fold(
222:         (RenderVec3::ZERO, RenderVec3::ZERO),
223:         |accumulated, light| {
224:             let radiance = render_vec3_or(light.color * light.intensity, RenderVec3::ZERO);
225:             (
226:                 accumulated.0 + radiance,
227:                 accumulated.1
228:                     + if light.affects_lightmapped_meshes {
229:                         radiance
230:                     } else {
231:                         RenderVec3::ZERO
232:                     },
233:             )
234:         },
235:     );
236:     (
237:         ambient.extend(1.0).to_array(),
238:         lightmapped_ambient.extend(1.0).to_array(),
239:     )
240: }
