10: pub(crate) struct SceneUniform {
11:     /// Current frame clip-from-world matrix. This may include temporal jitter.
12:     pub(crate) view_proj: [[f32; 4]; 4],
13:     /// Current frame clip-from-world matrix with temporal jitter removed.
14:     pub(crate) view_proj_unjittered: [[f32; 4]; 4],
