23:     pub(crate) motion_params: [f32; 4],
24:     /// xy = pixel jitter offset, z = Halton sequence index, w = active jitter flag.
25:     pub(crate) jitter_params: [f32; 4],
26:     /// xyz = camera world position, w = global material texture mip bias.
27:     pub(crate) camera_world_position: [f32; 4],
28:     /// xyz = orthographic world-space surface-to-camera direction (the camera backward axis),
29:     /// w = orthographic flag.
30:     pub(crate) camera_view_direction: [f32; 4],
31:     pub(crate) sky_horizon_color: [f32; 4],
32:     pub(crate) sky_zenith_color: [f32; 4],
