49: impl SceneUniform {
50:     /// 在场景上传前规范全局材质 mip 偏移；非有限输入不得进入 GPU uniform。
51:     pub(in crate::graphics::scene::scene_renderer) fn set_global_material_mip_bias(
52:         &mut self,
53:         mip_bias: f32,
54:     ) {
55:         self.camera_world_position[3] = if mip_bias.is_finite() {
56:             mip_bias.clamp(0.0, MAX_GLOBAL_MATERIAL_MIP_BIAS)
57:         } else {
58:             0.0
59:         };
60:     }
61: 
62:     /// 环境捕获完成后切换实时 IBL 采样元数据，调用方须提供对应 cubemap 资源。
63:     pub(in crate::graphics::scene::scene_renderer) fn use_realtime_ibl(
64:         &mut self,
65:         source_face_size: u32,
66:         pmrem_face_size: u32,
67:         pmrem_mip_count: u32,
68:     ) {
69:         self.environment_sample_params = [
70:             4.0,
71:             source_face_size.max(1) as f32,
72:             pmrem_face_size.max(1) as f32,
73:             pmrem_mip_count.max(1) as f32,
74:         ];
75:     }
76: 
77:     /// 仅环境捕获表面 pass 显式开启该策略，普通视口默认保持关闭。
78:     pub(in crate::graphics::scene::scene_renderer) fn use_environment_capture_surface_policy(
79:         &mut self,
80:     ) {
81:         self.sky_sun_params[3] = ENVIRONMENT_CAPTURE_SURFACE_POLICY_ENABLED;
82:     }
83: }
