15: /// 将选中模型的各局部 mesh 包围盒及选区锚点构成世界空间线条，交由 overlay 线条 pass 绘制。
16: /// 高亮描边受 outline_enabled 约束；锚点独立于高亮开关。
17: // TODO: [CR-SCENE-PRIM-0002] 直接 mesh 快照可绕过 model 绘制，但此路径只查询 streamer.model；需确认选中直接 mesh 时是否丢失包围盒。
18: pub(crate) fn build_selection_vertices(
19:     frame: &ViewportRenderFrame,
20:     streamer: &ResourceStreamer,
21: ) -> Vec<LineVertex> {
22:     let mut vertices = Vec::new();
23:     if let Some(highlights) = frame.overlays().highlights.as_ref() {
24:         if highlights.attributes().outline_enabled {
25:             let tint = highlights.attributes().tint_rgba;
26:             let color = Vec4::new(tint[0], tint[1], tint[2], tint[3]);
27:             visit_selected_meshes(frame.meshes(), highlights.entities(), |mesh_instance| {
28:                 let Some(model) = streamer.model(&mesh_instance.model.id()) else {
29:                     return;
30:                 };
31:                 for mesh in &model.meshes {
32:                     append_bounding_box_vertices(
33:                         &mut vertices,
34:                         mesh.bounds_min,
35:                         mesh.bounds_max,
36:                         mesh_instance.transform.matrix(),
37:                         color,
38:                     );
39:                 }
40:             });
41:         }
42:     }
43: 
44:     let camera = frame.effective_camera();
45:     for anchor in &frame.overlays().selection_anchors {
46:         append_cross(
47:             &mut vertices,
48:             anchor.position,
49:             anchor.size,
50:             anchor.color,
51:             camera.transform.right(),
52:             camera.transform.up(),
53:         );
54:     }
55: 
56:     vertices
57: }
