59: /// 小选区线性查找，大选区建立索引；两条路径都保留选中列表顺序并只取每个实体首个快照。
60: fn visit_selected_meshes<'a>(
61:     meshes: &'a [RenderMeshSnapshot],
62:     entities: &[EntityId],
63:     mut visit: impl FnMut(&'a RenderMeshSnapshot),
64: ) {
65:     if entities.len() <= INDEXED_SELECTION_LOOKUP_THRESHOLD {
66:         for owner in entities {
67:             if let Some(mesh) = meshes.iter().find(|mesh| mesh.node_id == *owner) {
68:                 visit(mesh);
69:             }
70:         }
71:         return;
72:     }
73: 
74:     let mut meshes_by_owner = HashMap::with_capacity(meshes.len());
75:     for mesh in meshes {
76:         meshes_by_owner.entry(mesh.node_id).or_insert(mesh);
77:     }
78:     for owner in entities {
79:         if let Some(mesh) = meshes_by_owner.get(owner) {
80:             visit(mesh);
81:         }
82:     }
83: }
