10: /// 将资源中的 wire_segments 投到实例世界空间；Shaded 直接跳过，WireOnly 对选中实体使用强调色。
11: pub(crate) fn build_wireframe_vertices(
12:     frame: &ViewportRenderFrame,
13:     streamer: &ResourceStreamer,
14: ) -> Vec<LineVertex> {
15:     let display_mode = frame.overlays().display_mode;
16:     if display_mode == DisplayMode::Shaded {
17:         return Vec::new();
18:     }
19:     let selection = if display_mode == DisplayMode::WireOnly {
20:         if let Some(highlights) = frame.overlays().highlights.as_ref() {
21:             let entities = highlights.entities();
22:             let mut selection = HashSet::with_capacity(entities.len());
23:             selection.extend(entities.iter().copied());
24:             selection
25:         } else {
26:             HashSet::new()
27:         }
28:     } else {
29:         HashSet::new()
30:     };
31: 
32:     let mut vertices = Vec::new();
33:     for mesh_instance in frame.meshes() {
34:         let Some(model) = streamer.model(&mesh_instance.model.id()) else {
35:             continue;
36:         };
37:         let color = match display_mode {
38:             DisplayMode::WireOverlay => Vec4::new(0.08, 0.09, 0.1, 0.9),
39:             DisplayMode::WireOnly => {
40:                 if selection.contains(&mesh_instance.node_id) {
41:                     Vec4::new(1.0, 0.9, 0.45, 1.0)
42:                 } else {
43:                     Vec4::new(0.86, 0.88, 0.93, 1.0)
44:                 }
45:             }
46:             DisplayMode::Shaded => Vec4::ONE,
47:         };
48:         let model_matrix = mesh_instance.transform.matrix();
49:         for mesh in &model.meshes {
50:             vertices.reserve(mesh.wire_segments.len().saturating_mul(2));
51:             for [start, end] in &mesh.wire_segments {
52:                 vertices.push(LineVertex::new(
53:                     model_matrix.transform_point3(*start),
54:                     color,
55:                 ));
56:                 vertices.push(LineVertex::new(model_matrix.transform_point3(*end), color));
57:             }
58:         }
59:     }
60:     vertices
61: }
